import { deepClone } from "../../commonHelpers/utils";
import { getWidthWithMargin } from "./getWidthWithMargin";
export const createDisplayingElements = (currentChildInd, elements, displayElements, widthProps) => (elInd) => {
    const currentWidth = widthProps.requiredWidth + getWidthWithMargin(elements[currentChildInd].childNodes[elInd]);
    const displayElementsClone = deepClone(displayElements);
    widthProps.requiredWidth = currentWidth;
    if (widthProps.requiredWidth < widthProps.width) {
        const blockName = elements[currentChildInd].dataset.name || "";
        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
        displayElementsClone[blockName] = displayElementsClone[blockName] ? [...displayElementsClone[blockName], elInd] : [elInd];
    }
    return displayElementsClone;
};
